+
+    document.getElementById('app').innerHTML = App();
+
+    const dialog = document.getElementById('deleteDialog');
+    const openButton = document.getElementById('openDialog');
+    const confirmButton = document.getElementById('confirmDelete');
+    const keepButton = document.getElementById('secondaryAction');
+    const status = document.getElementById('status');
+    const contentMount = document.getElementById('contentMount');
+    let lastTrigger = null;
+
+    function closeDialog() {
+      if (dialog.open) {
+        dialog.close();
+      }
+    }
+
+    openButton.addEventListener('click', () => {
+      lastTrigger = openButton;
+      dialog.showModal();
+    });
+
+    keepButton.addEventListener('click', () => {
+      status.textContent = 'Image kept in your library.';
+    });
+
+    confirmButton.addEventListener('click', () => {
+      closeDialog();
+      contentMount.closest('.panel').classList.add('is-deleted');
+      status.textContent = 'Image deleted from your library.';
+      openButton.disabled = true;
+      openButton.setAttribute('aria-disabled', 'true');
+      keepButton.disabled = true;
+    });
+
+    dialog.addEventListener('cancel', () => {
+      status.textContent = 'Delete canceled.';
+    });
+
+    dialog.addEventListener('close', () => {
+      if (lastTrigger && typeof lastTrigger.focus === 'function') {
+        lastTrigger.focus();
+      }
+    });
+
+    dialog.addEventListener('click', (event) => {
+      const rect = dialog.getBoundingClientRect();
+      const clickedOutside =
+        event.clientX < rect.left ||
+        event.clientX > rect.right ||
+        event.clientY < rect.top ||
+        event.clientY > rect.bottom;
+
+      if (clickedOutside) {
+        closeDialog();
+      }
+    });
