       background: linear-gradient(180deg, #f8faff 0%, #f3f6ff 100%);
     }

     .side-card {
       padding: 1rem;
       border-radius: var(--radius-lg);
       border: 1px solid var(--border);
       background: var(--surface);
     }

     .side-card h2 {
       margin: 0 0 0.4rem;
       font-size: 1rem;
     }

     .side-card p {
       margin: 0;
       line-height: 1.5;
       color: var(--muted);
     }

     .actions {
       display: flex;
       flex-wrap: wrap;
       gap: 0.75rem;
     }

     .button {
       appearance: none;
       border: 1px solid transparent;
       border-radius: 999px;
       padding: 0.85rem 1.1rem;
       font: inherit;
       font-weight: 600;
       line-height: 1;
       cursor: pointer;
       transition: transform 160ms ease, background-color 160ms ease, border-color 160ms ease, color 160ms ease;
     }

     .button:hover {
       transform: translateY(-1px);
     }

     .button:focus-visible {
       outline: 3px solid var(--focus);
       outline-offset: 3px;
     }

     .button.primary {
       background: var(--danger);
       color: white;
       box-shadow: 0 10px 24px rgba(192, 38, 38, 0.22);
     }

     .button.primary:hover {
       background: var(--danger-strong);
     }

     .button.ghost {
       background: var(--surface);
       border-color: var(--border);
       color: var(--text);
     }

     dialog {
       width: min(92vw, 560px);
       border: 1px solid var(--border);
       border-radius: 24px;
       padding: 0;
       background: var(--surface);
       color: var(--text);
       box-shadow: var(--shadow);
     }

     dialog::backdrop {
       background: var(--backdrop);
       backdrop-filter: blur(8px);
     }

     .dialog-inner {
       padding: 1.25rem;
     }

     .dialog-kicker {
       display: inline-flex;
       align-items: center;
       gap: 0.5rem;
       margin-bottom: 0.8rem;
       padding: 0.45rem 0.75rem;
       border-radius: 999px;
       background: #fef2f2;
       color: var(--danger-strong);
       font-size: 0.88rem;
       font-weight: 700;
     }

     .dialog-title {
       margin: 0;
       font-size: 1.4rem;
       line-height: 1.2;
     }

     .dialog-copy {
       margin: 0.7rem 0 0;
       color: var(--muted);
       line-height: 1.6;
     }

     .dialog-actions {
       display: flex;
       flex-wrap: wrap;
       justify-content: flex-end;
       gap: 0.75rem;
       margin-top: 1.35rem;
     }

     .dialog-actions .button {
       min-width: 8rem;
       justify-content: center;
     }

     .dialog-actions .button.destructive {
       background: var(--danger);
       color: white;
     }

     .dialog-actions .button.destructive:hover {
       background: var(--danger-strong);
     }

     .deleted-state {
       display: none;
       padding: 2rem;
       text-align: center;
     }

     .deleted-state h2 {
       margin: 0 0 0.4rem;
       font-size: 1.35rem;
     }

     .deleted-state p {
       margin: 0;
       color: var(--muted);
       line-height: 1.6;
     }

     .is-deleted .panel-grid {
       display: none;
     }

     .is-deleted .deleted-state {
       display: block;
     }

     @media (max-width: 760px) {
       .page {
         padding-inline: 0.75rem;
       }

       .panel-grid {
         grid-template-columns: 1fr;
       }

       .preview {
         border-right: 0;
         border-bottom: 1px solid var(--border);
       }
     }

     @media (forced-colors: active) {
       :root {
         --bg: Canvas;
         --surface: Canvas;
         --surface-2: Canvas;
         --text: CanvasText;
         --muted: CanvasText;
         --border: ButtonBorder;
         --accent: LinkText;
         --accent-strong: LinkText;
         --danger: ButtonText;
         --danger-strong: ButtonText;
         --focus: Highlight;
         --backdrop: CanvasText;
       }

       .panel,
       .side-card,
       dialog {
         forced-color-adjust: auto;
       }

       .button.primary,
       .button.ghost,
       .dialog-actions .button.destructive,
       .dialog-kicker {
         border-color: ButtonBorder;
         background: Canvas;
         color: ButtonText;
       }
     }
   </style>
 </head>
